// AUTO-GENERATED by scripts/bake-character-opinion.ts. Do not edit.
// Run `npm run bake:character-opinion` to refresh.
//
// The coefficients `Player.calculateCharacterOpinionRate`
// (PlayerOpinion.cs:1059) sums, and the band that rate falls in. Read by
// `$lib/game-detail/character-opinion`, which does the summing.

export interface OpinionCharacterBand {
	/** OPINIONCHARACTER_* zType. */
	readonly type: string;
	/** Inclusive upper bound on the rate; null on the top band, which is open-ended. */
	readonly threshold: number | null;
	/** Percent this band adds to the strength of a unit the character leads. */
	readonly strengthModifier: number;
}

// Ascending, which is also resolution order: `getOpinionFromRate`
// (InfoHelpers.cs:2302) takes the smallest threshold still at or above the
// rate, and anything above them all is the last.
export const OPINION_CHARACTER_BANDS: readonly OpinionCharacterBand[] = [
	{ type: "OPINIONCHARACTER_FURIOUS", threshold: -200, strengthModifier: -20 },
	{ type: "OPINIONCHARACTER_ANGRY", threshold: -100, strengthModifier: -10 },
	{ type: "OPINIONCHARACTER_UPSET", threshold: -1, strengthModifier: -5 },
	{ type: "OPINIONCHARACTER_CAUTIOUS", threshold: 99, strengthModifier: 0 },
	{ type: "OPINIONCHARACTER_PLEASED", threshold: 199, strengthModifier: 5 },
	{ type: "OPINIONCHARACTER_FRIENDLY", threshold: null, strengthModifier: 10 },
];

/** What one trait on the character does to their opinion of the leader. */
export interface TraitOpinion {
	/** Flat, for a trait the character's own player sees (`:121`). */
	readonly opinion?: number;
	/** Flat, when the leader carries the same trait (`:141`). */
	readonly opinionSame?: number;
	/** Per trait the LEADER carries (`:166`). */
	readonly traitOpinion?: Readonly<Record<string, number>>;
	/** Per law the player has active (`:194`). */
	readonly lawOpinion?: Readonly<Record<string, number>>;
	/** Per job the character holds (`:219`). */
	readonly jobOpinion?: Readonly<Record<string, number>>;
}

